B.a22=new A.al(B.jr,["Seviye 15","50 Odun & Ta\u015f","0.25 Ekmek / sn","1 Un + 1 Odun -> 1 Ekmek"],t.w)
B.a_R=s(["Kervan rotas\u0131 ba\u011flamadan \xf6nce en az 50 ekmek stoklay\u0131n."],t.s)
